create table public.profiles (id uuid primary key references auth.users on delete cascade, first_name text, last_name text, phone text, rating numeric default 5, created_at timestamptz default now());
create table public.vehicles (id uuid primary key default gen_random_uuid(), driver_id uuid references public.profiles(id) on delete cascade, make text, model text, year int, colour text, registration text, verification_status text default 'pending', created_at timestamptz default now());
create table public.campaigns (id uuid primary key default gen_random_uuid(), brand text not null, title text not null, area text, starts_on date, ends_on date, payment_pence int not null, status text default 'draft', created_at timestamptz default now());
create table public.campaign_assignments (id uuid primary key default gen_random_uuid(), campaign_id uuid references public.campaigns(id), driver_id uuid references public.profiles(id), status text default 'invited', progress int default 0, created_at timestamptz default now());
create table public.evidence (id uuid primary key default gen_random_uuid(), assignment_id uuid references public.campaign_assignments(id), driver_id uuid references public.profiles(id), storage_path text not null, evidence_type text, review_status text default 'pending', created_at timestamptz default now());
alter table public.profiles enable row level security; alter table public.vehicles enable row level security; alter table public.campaign_assignments enable row level security; alter table public.evidence enable row level security;
create policy "Drivers read own profile" on public.profiles for select using (auth.uid()=id); create policy "Drivers update own profile" on public.profiles for update using (auth.uid()=id);
create policy "Drivers manage own vehicles" on public.vehicles for all using (auth.uid()=driver_id) with check (auth.uid()=driver_id);
create policy "Drivers read assignments" on public.campaign_assignments for select using (auth.uid()=driver_id); create policy "Drivers update assignments" on public.campaign_assignments for update using (auth.uid()=driver_id);
create policy "Drivers manage evidence" on public.evidence for all using (auth.uid()=driver_id) with check (auth.uid()=driver_id);
